# VENDORED COPY -- generated by tools/build_addon.py from core/provenance.py
# Edit core/provenance.py, not this file.
#!/usr/bin/env python3
r"""
provenance.py -- record which install a derived artefact came from, and refuse
one that came from somewhere else.

WHY THIS IS ONE MODULE AND NOT SIX FIXES
----------------------------------------
Reading this repository's handoffs as a set, the same defect appears six times
wearing six costumes:

  * ``out/`` was not keyed by client, so eight installs shared one tree
  * ``parts._ACTION_CAT`` cached one motion catalogue per *process*, and a
    script walking three clients measured the first one three times
  * ``out/dll/`` holds artefacts from two installs and three dates; its
    ``rtti.md`` is still titled for one client over a body describing another
  * ``out/meshtex/`` was regenerated mid-measurement and the change was
    attributed to the code being measured
  * ``out/thumbs/manifest.json`` records *how* it rendered and never *what
    from*
  * the viewer suite gates on ``HAVE_ROOT`` -- "does a directory exist" -- so
    it cannot tell a wrong client from broken code

Those are not six bugs. They are one missing invariant, stated here once:

    **Every derived artefact records what it was derived from, and every
    loader refuses one it did not derive.**

Fixing it six times in six styles is how one of them ends up subtly wrong and
stays wrong -- which is the argument `safepath` already made for path
confinement, and it applies here for the same reason.

WHAT MAKES THIS CHECKABLE AT ALL
--------------------------------
`coroot.base_id` already answers "which install is this?" as
``<kind>-<fingerprint>``, where the fingerprint is a content hash of the
``ini/`` table layer.  This module does not invent identity; it writes that
answer down beside the data and compares it on the way back in.

``out/offsets_cache.json`` is the shape being generalised.  It keys on the
sha256 of the module bytes and `load_cache` returns ``None`` on mismatch --
the only loader in the repository that refuses a foreign cache rather than
trusting a path.  Everything here is that idea with the install as the key.

REFUSAL, NOT DEGRADATION
------------------------
`read_json` returns ``None`` when the stamp does not match, and the caller
must then say so out loud rather than carry on with less.  That is the rule
`coroot.find_derived` already states, with ``meshtex.scan_meshes`` named as
the cautionary tale: every one of the six failures above surfaced as a
*plausible answer*, never as an error, which is precisely what made them
expensive.  A wrong-client index loads as cleanly as a right one.

UNSTAMPED IS NOT FOREIGN, AND THE DIFFERENCE IS THE MIGRATION
-------------------------------------------------------------
An artefact built before this module existed carries no stamp.  That is not
evidence it is wrong -- only that nothing can vouch for it.  The two verdicts
are kept distinct (`UNSTAMPED` vs `FOREIGN`) because every artefact in the
tree is unstamped on the day this lands, and a check that cannot tell "not yet
migrated" from "provably the wrong client" would have to be switched off to be
usable, which is how a gate stops gating.

NO ABSOLUTE PATHS IN A STAMP
----------------------------
The stamp names the install by its *folder name* and fingerprint, never its
path.  ``tests/test_sanitization.py`` forbids absolute user paths in anything
publishable, and derived artefacts get quoted into documentation -- the mixed
``out/dll/rtti.md`` is exactly the kind of file that ends up pasted into a
handoff.  A stamp that leaked ``C:\Users\<name>\...`` would turn this safety
check into a PII hazard.

Pure stdlib, and imports nothing outside COre.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator, Optional

from . import coroot

__all__ = [
    "SCHEMA", "KEY", "MATCH", "FOREIGN", "UNSTAMPED", "UNKNOWN",
    "stamp", "optional_stamp", "wrap", "unwrap", "verdict", "describe",
    "orphaned_namespaces", "migration_plan",
    "read_json", "write_json", "sidecar_path", "stamp_file", "read_stamp",
    "Artefact", "audit",
]

#: Bumped only when the stamp's own shape changes incompatibly.  A reader
#: seeing a *newer* schema than it knows refuses, rather than guessing which
#: fields it can still trust.
SCHEMA = 1

#: The envelope key.  Chosen to be unlikely to collide with a payload's own
#: top-level keys; `wrap` asserts it does not.
KEY = "provenance"

MATCH = "match"
FOREIGN = "foreign"
UNSTAMPED = "unstamped"
#: Stamped BY THE BACKLOG SWEEP, not by the tool that built the artefact.
#: A distinct state on purpose. Writing a stamp onto a file built weeks ago
#: records the install configured NOW, a `generated` of now, and the sweeping
#: tool's name -- three claims about provenance that were never measured.
#: Folding that into `MATCH` would convert 119 honest "cannot be vouched for"
#: into 119 confident ones, joining the 15 stale artefacts that already report
#: `MATCH`, which is the defect this module exists to end.
#: `docs/provenance_staleness.md` section 4 states the rule this obeys:
#: **"stamped but not datable must be its own state and must never be folded
#: into fresh"**. This is that rule applied to the migration itself.
MIGRATED = "migrated"
UNKNOWN = "unknown"


def _now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _tool_name(tool: str = "") -> str:
    if tool:
        return str(tool)
    try:
        return Path(sys.argv[0]).name or "?"
    except Exception:                                    # pragma: no cover
        return "?"


def _install_name(root=None) -> str:
    """The install's folder name -- never its path.  See the module docstring."""
    try:
        d = Path(root) if root is not None else coroot.game_root()
        return Path(d).name
    except Exception:
        return ""


def stamp(root=None, tool: str = "", base: str = "", *,
          migrated: bool = False, base_source: str = "") -> dict:
    """A provenance record for an artefact derived from ``root``.

    ``base`` lets a caller that already computed `coroot.base_id` pass it in;
    the fingerprint hashes ~37 MB of ``ini/`` (about 50 ms), which is cheap
    once and wasteful in a loop.
    """
    bid = base or coroot.base_id(root)
    kind, _, fp = bid.partition("-")
    out = {
        "schema": SCHEMA,
        "base_id": bid,
        "kind": kind,
        "fingerprint": fp,
        "install": _install_name(root),
        "generated": _now(),
        "tool": _tool_name(tool),
    }
    if migrated:
        # `generated` and `tool` now describe the SWEEP, not the build. Kept
        # rather than omitted so a reader can see when the backlog was swept;
        # `migrated` is what stops either being read as the artefact's own age.
        out["migrated"] = True
        # WHERE THE INSTALL CAME FROM, because the two are not equal evidence.
        # An artefact under `out/indexes/<base-id>/` is filed under a namespace
        # that NAMES its install -- evidence. Anything else gets the configured
        # install, which is an ASSUMPTION. Saying which is the difference
        # between a record and a guess.
        out["base_source"] = base_source or "assumed"
    return out


def wrap(data: Any, root=None, tool: str = "", base: str = "") -> dict:
    """Put ``data`` in a stamped envelope: ``{provenance: {...}, data: ...}``.

    An envelope rather than extra top-level keys, because several artefacts
    here are keyed by *binary name* at the top level (``out/dll/exports.json``
    is ``{"graphic.dll": ...}``) and a sibling key would be indistinguishable
    from a payload entry -- which is a large part of why those files have no
    room to say what they came from today.
    """
    if isinstance(data, dict) and KEY in data:
        raise ValueError(f"payload already has a {KEY!r} key; refusing to shadow it")
    return {KEY: stamp(root, tool, base), "data": data}


def unwrap(doc: Any) -> tuple[Optional[dict], Any]:
    """Split a document into ``(stamp, payload)``.

    An unstamped document is returned as ``(None, doc)`` unchanged, so a
    reader can migrate gradually instead of failing on everything built
    before this existed.
    """
    cand = doc.get(KEY) if isinstance(doc, dict) else None
    # `schema` is what separates a stamp from a payload SECTION that happens
    # to be called "provenance".  `out/health.json` has one -- it holds the
    # audit's own result, and its `base_id` field names whichever install the
    # LAST health run was pointed at.  Without this check `read_stamp` handed
    # that section back as health.json's stamp, so `audit` reported its own
    # report as FOREIGN to every other install: a permanent false positive
    # wearing the exact word this audit reserves for a real fault, which is
    # the failure mode the keyed-artefact comment in `audit` already warns
    # about.  `wrap` refuses to shadow a payload key on the write side; that
    # guard cannot fire for a file written with a plain `json.dump`, so the
    # read side has to be able to tell the two apart on its own.
    if isinstance(cand, dict) and "schema" in cand:
        return cand, doc.get("data")
    return None, doc


def verdict_for_stamp(st: Optional[dict], expect: str) -> str:
    """The one place a stamp becomes a verdict.

    **Extracted because there were two.** `audit` carried its own inline copy
    of this decision, so folding `MIGRATED` into `MATCH` in `verdict` left the
    audit reporting the old answer -- caught by a mutation that reddened one
    of the two arms aimed at it and not the other. Two implementations of one
    decision is the divergence this module exists to prevent, appearing inside
    the module itself.
    """
    if st is None:
        return UNSTAMPED
    if st.get("schema", 0) > SCHEMA:
        return FOREIGN
    if not expect or expect == "unkeyed":
        return UNKNOWN
    if st.get("base_id") != expect:
        return FOREIGN
    # FOREIGN outranks MIGRATED deliberately: a swept stamp naming another
    # install is still PROVEN wrong, and proven beats unestablished.
    return MIGRATED if st.get("migrated") else MATCH


def verdict(doc: Any, root=None, base: str = "") -> str:
    """`MATCH`, `FOREIGN`, `UNSTAMPED` or `UNKNOWN` for a loaded document.

    `UNKNOWN` means *we* cannot say which install is configured -- an
    unreadable or unfingerprintable root -- and is deliberately not `MATCH`:
    `coroot.base_id` already refuses to let a broken install silently share
    whatever was built last, and this keeps that promise on the read side.
    """
    st, _ = unwrap(doc)
    if st is None:
        return UNSTAMPED
    return verdict_for_stamp(st, base or coroot.base_id(root))


def describe(doc: Any) -> str:
    """A short human summary of where a document came from, for error text."""
    st, _ = unwrap(doc)
    if st is None:
        return "unstamped"
    who = st.get("base_id") or "?"
    when = st.get("generated") or "?"
    tool = st.get("tool") or "?"
    return f"{who}, built {when} by {tool}"


def optional_stamp(root, tool: str = "") -> Optional[dict]:
    """`stamp` for a caller that must not fail, and must not lie either.

    Two answers only: a stamp that names a real install, or ``None``.

    `stamp` itself never fails -- `base_id` degrades to ``unkeyed`` when the
    fingerprint cannot be computed, which is right for an artefact keyed by
    directory and **wrong for a record embedded in data that travels**. An
    ``unkeyed`` stamp resolves against no install while reading exactly like a
    measured one, which is the failure mode this module was written to end.
    ``None`` is the honest answer and every reader here already has a state
    for it.

    Used by the collectors, which write provenance into COmmunity Library
    entries: an entry copied to another machine must either name a source
    install that machine can check, or say plainly that nothing recorded one.
    """
    if root is None:
        return None
    try:
        st = stamp(root, tool=tool)
    except Exception:
        return None
    if str(st.get("base_id") or "") in ("", "unkeyed"):
        return None
    return st


# ---------------------------------------------------------------------------
# JSON artefacts
# ---------------------------------------------------------------------------

def write_json(rel: str, data: Any, root=None, *, tool: str = "",
               base: str = "", indent: int = 2) -> Path:
    """Write a stamped JSON artefact to its keyed location and return the path.

    Resolves through `coroot.derived_path`, so a caller cannot accidentally
    write to the unkeyed literal -- which is how seven ``dump_*`` tools came
    to share one ``out/dll/``.
    """
    p = coroot.derived_path(rel, root)
    p.parent.mkdir(parents=True, exist_ok=True)
    doc = wrap(data, root, tool, base)
    p.write_text(json.dumps(doc, indent=indent), encoding="utf-8")
    return p


def read_json(rel: str, root=None, *, strict: bool = True,
              base: str = "") -> Optional[Any]:
    """Read a stamped JSON artefact, or ``None`` if it cannot be vouched for.

    ``strict`` (the default) refuses anything that is not `MATCH`.  Pass
    ``strict=False`` during migration to accept `UNSTAMPED` -- but never
    `FOREIGN`, which is always a refusal: an artefact that *says* it came from
    another install is the one case where we have positive evidence of the bug
    this module exists to stop.

    Returns the payload, not the envelope.  A caller that gets ``None`` must
    say so out loud rather than continue with less.
    """
    p = coroot.find_derived(rel, root)
    if p is None:
        return None
    try:
        doc = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    v = verdict(doc, root, base)
    if v == MATCH or (not strict and v in (UNSTAMPED, UNKNOWN)):
        return unwrap(doc)[1]
    return None


# ---------------------------------------------------------------------------
# artefacts that are not JSON
# ---------------------------------------------------------------------------

def sidecar_path(path) -> Path:
    """Where the stamp for a non-JSON artefact lives: ``<name>.provenance.json``.

    Markdown reports, ``.png`` thumbnails and binary indexes have nowhere to
    put an envelope, and rewriting them to carry one would change formats that
    other tools parse.  A sidecar keeps the artefact byte-identical.
    """
    p = Path(path)
    return p.with_name(p.name + ".provenance.json")


def _sha256_file(path: Path) -> str:
    """sha256 of a file's bytes, streamed. Counted, so the cost arm can assert
    how many files a second audit re-hashes (it must be zero)."""
    global _HASH_CALLS
    _HASH_CALLS += 1
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


#: Data-file hashes computed, process-wide. The cost arm reads it.
_HASH_CALLS = 0


def stamp_file(path, root=None, *, tool: str = "", base: str = "",
               migrated: bool = False, base_source: str = "") -> Path:
    """Write a sidecar stamp beside an existing artefact -- LAST.

    **THE SIDECAR NOW RECORDS THE sha256 OF THE BYTES IT DESCRIBES**, and the
    ordering is the contract: a caller writes its data first and calls this
    after, so a completed write always ends with a fresh sidecar.

    Why the hash, and the honest size of what it buys. The sidecar recorded
    base, tool, install and time -- and nothing about the bytes -- so a torn
    pair was UNDETECTABLE: new data beside the previous sidecar, or a
    hand-copied artefact carrying some other build's stamp, read exactly like
    a consistent pair. **Cross-base trust was never at risk**: each base owns
    its own `out/indexes/<base-id>/` directory, so both halves of any pair
    claim the same base and the verdict is the same either way. What the
    hash fixes is MISATTRIBUTION -- an old tool and time presented as
    describing new bytes -- which becomes detectable instead of silent.

    Written through a temp file and `os.replace`, so a reader never sees a
    half-written sidecar. That is atomic per FILE, not per data+sidecar PAIR
    -- which is exactly why the hash exists: the pair is verified by content
    when it is read, not assumed consistent because it was written in order.
    """
    p = Path(path)
    sc = sidecar_path(p)
    sc.parent.mkdir(parents=True, exist_ok=True)
    rec = stamp(root, tool, base, migrated=migrated,
                base_source=base_source)
    if p.is_file():
        rec["sha256"] = _sha256_file(p)
    tmp = sc.with_name(sc.name + ".tmp")
    tmp.write_text(json.dumps(rec, indent=2), encoding="utf-8")
    os.replace(tmp, sc)
    return sc


def _creation_ns(st: os.stat_result) -> int:
    """CREATION time -- named, not inferred.

    MEASURED on this box, CPython 3.14.6 on Windows 11, with `os.stat`:

        case                                  ctime    mtime    birthtime
        shutil.copy2: the COPY vs its SOURCE  CHANGED  same     CHANGED
        temp file + os.replace onto target    CHANGED  CHANGED  CHANGED
        in-place same-size overwrite          same     CHANGED  same
        st_ctime_ns == st_birthtime_ns on an untouched file: True

    So on this interpreter st_ctime IS creation time today. It is named here
    as `st_birthtime_ns` anyway, because Python documents st_ctime as moving
    toward METADATA-CHANGE time on Windows: a key justified by "ctime is
    creation" would silently stop being justified the day that lands.
    `st_birthtime_ns` names the property actually relied on. Fallback to
    st_ctime_ns only where birthtime is absent (older Pythons).
    """
    return getattr(st, "st_birthtime_ns", None) or st.st_ctime_ns


#: (path, size, creation_ns, mtime_ns, sha256 of the sidecar's bytes) ->
#: "does the recorded sha256 match the data?"  Per process.
_VERIFIED: dict[tuple, bool] = {}


def _data_matches(p: Path, sc_bytes: bytes, recorded: str) -> bool:
    """Does `p` still hash to `recorded`? Cached, because `audit()` walks ALL
    of out/ and `firstrun.js` polls it every 1.5 s while a first-run job is
    busy -- which is exactly when artefacts are being written. Re-hashing
    every stamped file per poll is the cost this cache removes.

    WHAT EACH KEY TERM CATCHES, from the measurement in `_creation_ns`:
      * creation_ns  -- a COPY (a copy cannot preserve it) and a temp-then-
                        replace write. Both produce a new file.
      * mtime_ns     -- an IN-PLACE overwrite, which does NOT change creation
                        time. That is how `meshtex --coverage` writes today,
                        so this term is doing real work, not decoration.
      * size         -- cheap, and catches most rewrites on its own.
      * sidecar sha  -- any rewrite of the stamp itself; `_now()` makes every
                        completed build's sidecar bytes different.
    NOT CAUGHT, and out of scope: a same-size in-place rewrite that ALSO
    forges mtime back with os.utime. That is deliberate tampering, which a
    provenance stamp does not defend against.

    "Verify once per process" was rejected: the torn state forms WHILE the
    viewer runs -- a bootstrap writing beside a polling page.
    """
    try:
        st = p.stat()
    except OSError:
        return False
    key = (str(p), st.st_size, _creation_ns(st), st.st_mtime_ns,
           hashlib.sha256(sc_bytes).hexdigest())
    hit = _VERIFIED.get(key)
    if hit is None:
        try:
            hit = _sha256_file(p) == recorded
        except OSError:
            hit = False
        _VERIFIED[key] = hit
    return hit


def read_stamp(path) -> Optional[dict]:
    """The stamp for ``path`` -- from its envelope if JSON, else its sidecar.

    A sidecar carrying a `sha256` is trusted only if the data still hashes to
    it. A MISMATCH returns None -- i.e. UNSTAMPED -- which every caller
    already handles for same-base use, so a torn or hand-copied pair adds no
    new state and no new branch anywhere. A sidecar with NO `sha256` (every
    one written before this change) reads exactly as it always did: that is
    the compatibility control, and it is what stops this from quietly
    invalidating every existing sidecar on the box.
    """
    p = Path(path)
    sc = sidecar_path(p)
    if sc.is_file():
        try:
            raw = sc.read_bytes()
            rec = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            return None
        recorded = rec.get("sha256") if isinstance(rec, dict) else None
        if recorded and not _data_matches(p, raw, recorded):
            return None
        return rec
    if p.suffix.lower() == ".json":
        try:
            return unwrap(json.loads(p.read_text(encoding="utf-8")))[0]
        except (OSError, json.JSONDecodeError):
            return None
    return None


# ---------------------------------------------------------------------------
# the audit
# ---------------------------------------------------------------------------

#: Trees the audit does not walk.  Each is runtime output rather than a
#: derived index: capture sessions are per-run, and the thumbnail and log
#: trees hold tens of thousands of files whose identity is already content
#: addressed (`thumbs.py` keys each entry by the hash of the mesh and texture
#: bytes, which is why they were safe by accident).
AUDIT_SKIP = ("out/sessions", "out/companion-logs", "out/thumbs/servers")

#: Artefacts that are legitimately install-independent, with the reason.
#: Anything *not* listed here and not per-base is reported as unclassified --
#: the point of the audit is that this list is currently far too short to
#: account for what is in the tree.
GLOBAL_OK = {
    "out/opcodes.json": "a protocol table, built from refs/, not from an install",
    "out/offsets_cache.json": "self-guarding: keyed on the sha256 of the module bytes",
    "out/health.json": "a report about this checkout, rewritten on every run",
    # A log of action codes named by eye. Every row carries its own `install`
    # and the sha256 of the clip that was watched, so the install is a COLUMN
    # and the file is about action codes rather than about one client. Twinned
    # with the `coroot.GLOBAL` entry: that one decides where the path
    # resolves, this one keeps the audit from reporting it unclassified.
    "out/action_names.json": (
        "a log of action codes named by eye; each row carries its own install "
        "and the sha256 of the clip, so the install is a column"),
}


class Artefact:
    """One file the audit looked at, and what it could say about it."""

    __slots__ = ("rel", "keyed", "verdict", "stamp", "bytes")

    def __init__(self, rel: str, keyed: bool, v: str,
                 st: Optional[dict], size: int):
        self.rel = rel
        self.keyed = keyed
        self.verdict = v
        self.stamp = st
        self.bytes = size

    @property
    def unclassified(self) -> bool:
        """In a namespace that cannot distinguish installs, and not declared
        install-independent.  This is the fail-open case."""
        return not self.keyed and self.rel not in GLOBAL_OK

    def as_dict(self) -> dict:
        return {"path": self.rel, "keyed": self.keyed, "verdict": self.verdict,
                "unclassified": self.unclassified, "bytes": self.bytes,
                "from": (self.stamp or {}).get("base_id", "")}


def _iter_files(out: Path) -> Iterator[Path]:
    skip = tuple(s.replace("/", os.sep) for s in AUDIT_SKIP)
    for p in out.rglob("*"):
        if not p.is_file() or p.name.endswith(".provenance.json"):
            continue
        s = str(p)
        if any(sep in s for sep in skip):
            continue
        if p.suffix.lower() in (".json", ".md"):
            yield p


def orphaned_namespaces(repo=None, live: str = "") -> list[dict]:
    """Index namespaces under ``out/indexes/`` that no declared install claims.

    A namespace is orphaned when its directory name is not the `base_id` of
    any install the user has declared.  That happens legitimately -- an
    install was deleted or moved -- and it happened *illegitimately* for
    months, because `base_fingerprint` hashed the files a client rewrites at
    shutdown, so merely launching a client stranded its own index and built a
    fresh one beside it.  Three CCO namespaces coexisted that way.

    Reported, never deleted.  These are large (hundreds of MB) and a tool
    that removes them on its own inference is a tool nobody should run.
    """
    repo = Path(repo) if repo is not None else Path(__file__).resolve().parent.parent
    root_dir = repo / coroot.INDEX_ROOT.replace("/", os.sep)
    if not root_dir.is_dir():
        return []
    claimed = set()
    try:
        for decl in (coroot.read_settings().get(coroot.KINDS_KEY) or {}):
            bid = coroot.base_id(decl)
            if bid and bid != "unkeyed":
                claimed.add(bid)
    except Exception:                                    # pragma: no cover
        pass
    if live:
        claimed.add(live)
    out = []
    for d in sorted(root_dir.iterdir()):
        if not d.is_dir() or d.name in claimed:
            continue
        size = 0
        try:
            size = sum(f.stat().st_size for f in d.rglob("*") if f.is_file())
        except OSError:                                  # pragma: no cover
            pass
        out.append({"name": d.name, "bytes": size,
                    "path": str(d.relative_to(repo).as_posix())})
    return out


def migration_plan(repo=None) -> list[dict]:
    """Orphaned namespaces that can be *renamed* onto a live one, and why.

    Changing what `coroot.base_fingerprint` hashes re-keys every install
    without changing what any index actually describes: the same install,
    under a new name.  So the old directory is still correct content, and
    renaming it avoids a rebuild that may not even be reproducible -- the
    entity crawl needs a server dump (`artcrawl --sql`) nobody may still have.

    A rename is only offered when it is **unambiguous**: exactly one orphan
    shares the live namespace's kind prefix.  CCO currently has three, so it
    gets ``"ambiguous"`` and a human decides.  That restraint is the same rule
    `coroot.base_id` states -- a missing index means "build me", never "borrow
    another base's answers" -- and borrowing is exactly what a wrong rename
    would be.

    Returns entries with ``action`` in ``rename`` | ``ambiguous`` | ``stale``.
    Plans only; nothing here moves a file.
    """
    repo = Path(repo) if repo is not None else Path(__file__).resolve().parent.parent
    root_dir = repo / coroot.INDEX_ROOT.replace("/", os.sep)
    if not root_dir.is_dir():
        return []
    live = {}
    try:
        for decl in (coroot.read_settings().get(coroot.KINDS_KEY) or {}):
            bid = coroot.base_id(decl)
            if bid and bid != "unkeyed":
                live[bid] = bid.rsplit("-", 1)[0]
    except Exception:                                    # pragma: no cover
        return []
    orphans = [d.name for d in sorted(root_dir.iterdir())
               if d.is_dir() and d.name not in live]
    out = []
    for bid, kind in sorted(live.items()):
        cands = [o for o in orphans if o.rsplit("-", 1)[0] == kind]
        if not cands:
            continue
        exists = (root_dir / bid).is_dir()
        if len(cands) == 1 and not exists:
            out.append({"action": "rename", "from": cands[0], "to": bid,
                        "why": "exactly one orphan of this kind"})
        elif len(cands) == 1 and exists:
            out.append({"action": "stale", "from": cands[0], "to": bid,
                        "why": "the live namespace already exists; the orphan "
                               "is superseded and can be deleted by hand"})
        else:
            out.append({"action": "ambiguous", "from": cands, "to": bid,
                        "why": f"{len(cands)} orphans share this kind -- "
                               "choosing one would be a guess"})
    return out


#: `<kind>-<12 hex>` -- the shape `coroot.base_id` produces. Matched against a
#: FILENAME so an artefact that names its own install (`viewer_verdict_<base>`)
#: is filed on evidence rather than on the configured install.
_BASE_IN_NAME = re.compile(r"[a-z][a-z0-9]*-[0-9a-f]{12}")


def expected_base(rel: str, configured: str) -> tuple[str, str]:
    """``(base_id, evidence)`` -- which install an artefact CLAIMS, and how.

    **The one place this is decided**, because deciding it twice is how the
    12-false-FOREIGN incident happened during this module's own migration:
    the sweep read an install out of a FILENAME
    (``viewer_verdict_<base-id>.json``) and filed it on that evidence, while
    `audit` still recognised only the ``out/indexes/<base-id>/`` namespace and
    therefore compared those twelve against whichever install was configured.
    Twelve correctly-filed verdict records reported FOREIGN -- the same false
    positive the keyed-artefact comment in `audit` already describes, arriving
    through a second route because there were two implementations of "what
    does this artefact claim".

    `evidence` is ``namespace`` | ``filename`` | ``assumed``, and the caller
    is expected to keep them distinct: the first two are evidence, the third
    is the configured install standing in for one.
    """
    prefix = f"{coroot.INDEX_ROOT}/"
    if rel.startswith(prefix):
        tail = rel[len(prefix):].split("/", 1)
        if tail and tail[0]:
            return tail[0], "namespace"
    m = _BASE_IN_NAME.search(rel.rsplit("/", 1)[-1])
    if m:
        return m.group(0), "filename"
    return configured, "assumed"


def migrate(repo=None, root=None, *, apply: bool = False,
            tool: str = "provenance --migrate") -> dict:
    """Stamp every UNSTAMPED artefact under ``out/`` as `MIGRATED`.

    **A PLAN BY DEFAULT.** ``apply=True`` writes sidecars; nothing else here
    touches a file, and a sidecar is deletable, so the sweep is reversible.

    WHAT THIS DOES AND DOES NOT CLAIM
    ---------------------------------
    It does not establish provenance -- it cannot. It records that the
    artefact was present in this tree when the sweep ran, and under which
    namespace. **That is worth doing because the unstamped population is
    invisible to every comparand in `docs/provenance_staleness.md` section 6**:
    `out/wdf/`'s files are the shared global inputs whose staleness poisons
    `meshtex`, and they have no stamp to date. Stamping them puts them in the
    checkable population; `MIGRATED` is what stops that being mistaken for
    having checked them.

    The install is taken from the artefact's own ``out/indexes/<base-id>/``
    namespace where it has one -- evidence -- and from the configured install
    otherwise -- an assumption. `base_source` records which, per artefact,
    because a sweep that presented both as the same thing would be making the
    error it exists to avoid.
    """
    repo = Path(repo) if repo is not None else Path(__file__).resolve().parent.parent
    rep = audit(repo, root)
    prefix = f"{coroot.INDEX_ROOT}/"
    plan, skipped = [], []
    for rel in rep["unstamped"]:
        # GLOBAL_OK artefacts are DECLARED install-independent, with a reason
        # each. Stamping one with a base_id would assert it belongs to an
        # install -- the opposite of what the declaration says, and a claim
        # the sweep has no business making. Skipped and reported, not stamped.
        if rel in GLOBAL_OK:
            skipped.append({"rel": rel, "why": GLOBAL_OK[rel]})
            continue
        bid, src = expected_base(rel, rep["base_id"])
        plan.append({"rel": rel, "base_id": bid, "base_source": src})
    written, failed = [], []
    if apply:
        for e in plan:
            p = repo / e["rel"].replace("/", os.sep)
            if not p.is_file():
                continue
            try:
                stamp_file(p, root, tool=tool, base=e["base_id"],
                           migrated=True, base_source=e["base_source"])
                written.append(e["rel"])
            except OSError as exc:                       # noqa: PERF203
                failed.append({"rel": e["rel"], "error": str(exc)})
    return {
        "applied": apply,
        "planned": len(plan),
        "written": len(written),
        "failed": failed,
        "from_namespace": sum(1 for e in plan if e["base_source"] == "namespace"),
        "from_filename": sum(1 for e in plan if e["base_source"] == "filename"),
        "assumed": sum(1 for e in plan if e["base_source"] == "assumed"),
        "skipped_global": skipped,
        "plan": plan,
    }


def audit(repo=None, root=None) -> dict:
    """Walk ``out/`` and report what can and cannot be vouched for.

    Does not read payloads -- only each artefact's stamp and its location --
    so it stays cheap enough to run from `health.py` on every invocation.
    """
    repo = Path(repo) if repo is not None else Path(__file__).resolve().parent.parent
    out = repo / "out"
    base = coroot.base_id(root)
    items: list[Artefact] = []
    if out.is_dir():
        prefix = f"{coroot.INDEX_ROOT}/"
        for p in _iter_files(out):
            rel = p.relative_to(repo).as_posix()
            keyed = rel.startswith(prefix)
            # An artefact under `out/indexes/<base-id>/` is claimed by THAT
            # namespace, not by whichever install happens to be configured.
            # Comparing every keyed artefact against the configured base
            # reported a correctly-filed 6090 index as FOREIGN while 5517 was
            # selected -- a false positive, and the worst possible kind: it
            # is the exact word this audit uses for a real fault, so it would
            # have taught people to disbelieve it.
            expect, _evidence = expected_base(rel, base)
            # Swept artefacts count apart from MATCH so the backlog stays
            # visible after a sweep -- one that drove the number to zero would
            # hide the thing it was run to expose. Through the SHARED decision
            # rather than a second copy of it.
            v = verdict_for_stamp(read_stamp(p), expect)
            items.append(Artefact(rel, keyed, v, read_stamp(p),
                                  p.stat().st_size))

    foreign = [a for a in items if a.verdict == FOREIGN]
    unclassified = [a for a in items if a.unclassified]
    unstamped = [a for a in items if a.verdict == UNSTAMPED]
    migrated = [a for a in items if a.verdict == MIGRATED]
    return {
        "base_id": base,
        "scanned": len(items),
        "artefacts": [a.as_dict() for a in items],
        "foreign": [a.rel for a in foreign],
        "unclassified": [a.rel for a in unclassified],
        "unstamped": [a.rel for a in unstamped],
        "migrated": [a.rel for a in migrated],
        "orphaned": orphaned_namespaces(repo, base),
        # Foreign is the only *proven* fault. Unstamped is the migration
        # backlog, and unclassified is the fail-open namespace -- both are
        # reported, neither is an error yet. Phase 2 turns the second one red.
        "ok": not foreign,
        "fix": ("Artefacts in an unkeyed namespace cannot say which install "
                "they describe. Build them through `provenance.write_json` "
                "(or stamp them with `provenance.stamp_file`) so a reader can "
                "refuse a foreign one."),
    }


def main(argv: Optional[list[str]] = None) -> int:
    import argparse
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[1],
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    coroot.add_root_argument(ap)
    ap.add_argument("--json", action="store_true", help="machine-readable")
    ap.add_argument("--repo", default=None,
                    help="the checkout whose out/ to walk. Defaults to this "
                         "one -- and out/ is gitignored and PER-TREE, so from "
                         "a linked worktree the default walks nothing and "
                         "reports a confident zero")
    ap.add_argument("--migrate", action="store_true",
                    help="stamp every UNSTAMPED artefact as migrated. Plans "
                         "only unless --apply is given")
    ap.add_argument("--apply", action="store_true",
                    help="with --migrate, actually write the sidecars")
    a = ap.parse_args(argv)
    try:
        root = coroot.root_from_args(a)
    except SystemExit:
        raise
    except Exception:
        root = None
    if a.migrate:
        m = migrate(a.repo, root, apply=a.apply)
        if a.json:
            print(json.dumps(m, indent=2))
            return 0
        head = "WROTE" if m["applied"] else "would stamp (plan only -- pass --apply)"
        print(f"{head}: {m['written'] if m['applied'] else m['planned']} "
              f"artefact(s) as MIGRATED")
        print(f"  install from its own namespace : {m['from_namespace']}"
              "   <- evidence")
        print(f"  install ASSUMED from the config: {m['assumed']}"
              "   <- not evidence")
        for e in m["plan"][:25]:
            print(f"    {e['base_source']:9} {e['base_id']:24} {e['rel']}")
        if len(m["plan"]) > 25:
            print(f"    ... and {len(m['plan']) - 25} more")
        for f in m["failed"]:
            print(f"    FAILED {f['rel']}: {f['error']}")
        return 1 if m["failed"] else 0

    rep = audit(a.repo, root)
    if a.json:
        print(json.dumps(rep, indent=2))
        return 0 if rep["ok"] else 1
    print(f"install    : {rep['base_id']}")
    print(f"scanned    : {rep['scanned']} derived artefact(s) under out/")
    print(f"foreign    : {len(rep['foreign'])}   (built from another install)")
    print(f"unstamped  : {len(rep['unstamped'])}   (cannot be vouched for)")
    print(f"migrated   : {len(rep.get('migrated', []))}   (swept, provenance "
          "NOT established -- deliberately not counted as match)")
    print(f"unclassified: {len(rep['unclassified'])}  (unkeyed namespace)")
    for rel in rep["foreign"]:
        print(f"  FOREIGN      {rel}")
    for rel in rep["unclassified"][:40]:
        print(f"  unclassified {rel}")
    if len(rep["unclassified"]) > 40:
        print(f"  ... and {len(rep['unclassified']) - 40} more")
    return 0 if rep["ok"] else 1


if __name__ == "__main__":                               # pragma: no cover
    raise SystemExit(main())
